views.mermaid:
flowchart TB
  subgraph people["People"]
    employee["Employee"]
    reviewer["Assigned reviewer"]
    research_operator["Research operator"]
  end
  subgraph franark["Franark boundary"]
    portal["Assessment portal"]
    workbench["Agent workbench"]
    lab["Capabilities lab"]
    knowledge_hub["Knowledge hub"]
  end
  employee --> portal
  employee --> workbench
  reviewer --> portal
  research_operator --> lab
  classDef pilot fill:#e7f1ff,stroke:#326cb0,color:#111;
  class portal,workbench,lab pilot;
  classDef existing fill:#edf7e8,stroke:#587b42,color:#111;
  classDef logical fill:#f2f4f7,stroke:#687787,color:#111;
  class employee,reviewer,research_operator logical;
  classDef prepared fill:#fff4d7,stroke:#986b21,color:#111,stroke-dasharray:6 4;
  classDef proposed fill:#ffffff,stroke:#788493,color:#111,stroke-dasharray:6 4;
  class knowledge_hub proposed;

flowchart TB
  subgraph adapters["Franark adapters"]
    sign_in["Sign-in adapter"]
    repository["Record repository"]
    model_adapter["Model adapter"]
    notification_draft["Notification draft"]
  end
  subgraph sfc_services["SFC account connections"]
    entra["Microsoft Entra"]
    azure_sql[("Azure SQL")]
    openai["OpenAI API"]
    microsoft_graph["Microsoft Graph"]
  end
  sign_in -.->|"verify identity"| entra
  repository -.->|"persist records"| azure_sql
  model_adapter -.->|"bounded requests"| openai
  notification_draft -.->|"future delivery"| microsoft_graph
  classDef pilot fill:#e7f1ff,stroke:#326cb0,color:#111;
  class repository,model_adapter,notification_draft pilot;
  classDef existing fill:#edf7e8,stroke:#587b42,color:#111;
  classDef logical fill:#f2f4f7,stroke:#687787,color:#111;
  classDef prepared fill:#fff4d7,stroke:#986b21,color:#111,stroke-dasharray:6 4;
  class sign_in,entra,azure_sql,openai prepared;
  classDef proposed fill:#ffffff,stroke:#788493,color:#111,stroke-dasharray:6 4;
  class microsoft_graph proposed;

flowchart TB
  subgraph task_context["Task context tools"]
    select["Select relevant evidence"]
    fields["Keep requested fields"]
    extract["Extract source sentences"]
  end
  subgraph storage_history["Storage and history tools"]
    delta["Create exact change patch"]
    pack["Compress stored text"]
    timeline["Coalesce unchanged events"]
  end
  classDef pilot fill:#e7f1ff,stroke:#326cb0,color:#111;
  class select,fields,extract,delta,pack,timeline pilot;
  classDef existing fill:#edf7e8,stroke:#587b42,color:#111;
  classDef logical fill:#f2f4f7,stroke:#687787,color:#111;
  classDef prepared fill:#fff4d7,stroke:#986b21,color:#111,stroke-dasharray:6 4;
  classDef proposed fill:#ffffff,stroke:#788493,color:#111,stroke-dasharray:6 4;

erDiagram
 form_definitions ||--o{ submissions : defines
 submissions ||--o{ submission_events : records
 submissions |o--o{ submissions : supersedes
 runs ||--o{ events : records
 runs |o--o{ measurements : attributes
 form_definitions {
   string form_key PK
   text definition_json
 }
 submissions {
   string id PK
   string form_key FK
   string supersedes_id FK
   text answers_json
   text signature_json
   string payload_sha256
 }
 submission_events {
   int id PK
   string submission_id FK
   string actor_subject
 }
 runs {
   string id PK
   string owner_subject
 }
 events {
   int id PK
   string run_id FK
 }
 measurements {
   int id PK
   string run_id FK
 }
